import{_ as a,o as n,c as t,a1 as s}from"./chunks/framework.CiMD_7j0.js";const h=JSON.parse('{"title":"Architecture & Request Flow","description":"","frontmatter":{"AIGC":{"ContentProducer":"001191110102MAD55U9H0F10002","ContentPropagator":"001191110102MAD55U9H0F10002","Label":"1","ProduceID":"1469312a-a5c1-4c5c-9353-431da0f19cf8","PropagateID":"1469312a-a5c1-4c5c-9353-431da0f19cf8","ReservedCode1":"cee9930a-0152-49dc-8037-8ac9a652a6d9","ReservedCode2":"cee9930a-0152-49dc-8037-8ac9a652a6d9"}},"headers":[],"relativePath":"en/guide/python/architecture.md","filePath":"en/guide/python/architecture.md","lastUpdated":null}'),i={name:"en/guide/python/architecture.md"};function o(r,e,d,p,c,l){return n(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="architecture-request-flow" tabindex="-1">Architecture &amp; Request Flow <a class="header-anchor" href="#architecture-request-flow" aria-label="Permalink to &quot;Architecture &amp; Request Flow&quot;">​</a></h1><h2 id="application-startup" tabindex="-1">Application Startup <a class="header-anchor" href="#application-startup" aria-label="Permalink to &quot;Application Startup&quot;">​</a></h2><p>The lifespan in <code>backend/src/main.py</code> starts the app in this order:</p><ol><li>Initialize logging, middleware and exception handlers.</li><li>Initialize the database connection; the dev environment may auto-create tables.</li><li>Run core seed data to ensure default departments, roles and menus exist.</li><li>Scan <code>backend/src/plugins/builtin</code>, sync plugin metadata and enabled state.</li><li>Execute <code>install()</code> on enabled plugins, then register HTTP routes, MCP tools and event listeners.</li><li>Register MCP HTTP routes and dispatch the <code>APP_STARTUP</code> event.</li></ol><p>On shutdown, plugins unload their runtime resources first, then the database pool closes.</p><h2 id="backend-layering" tabindex="-1">Backend Layering <a class="header-anchor" href="#backend-layering" aria-label="Permalink to &quot;Backend Layering&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP Request</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Middleware (request id, CORS, exception filter, operation log)</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>FastAPI Router</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Dependency (get_db / get_current_user / require_permission)</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>CRUD / Service</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>SQLAlchemy Model + AsyncSession</span></span></code></pre></div><p>The routing layer handles parameter validation and response format; business rules live in service functions; database commits stay inside the transaction boundary of business operations. The unified success response is <code>{ code, msg, data }</code>; business exceptions are converted by the global handler into the same error structure.</p><h2 id="frontend-routing" tabindex="-1">Frontend Routing <a class="header-anchor" href="#frontend-routing" aria-label="Permalink to &quot;Frontend Routing&quot;">​</a></h2><p>The admin panel loads user info and the menu tree on startup. <code>frontend/src/router/index.ts</code> uses <code>import.meta.glob(&#39;@/views/**/*.vue&#39;)</code> to resolve the menu <code>component</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Menu component: apehub_web/admin/Config</span></span>
<span class="line"><span>Page file:       frontend/src/views/apehub_web/admin/Config.vue</span></span>
<span class="line"><span>Access path:     /apehub-web/admin/config</span></span></code></pre></div><p>If the component is missing, no dynamic route is generated and users hit a 404. So the menu registration, page file and permission identifiers must be delivered as one plugin version.</p><h2 id="apehub-web-s-three-api-groups" tabindex="-1">Apehub_web&#39;s Three API Groups <a class="header-anchor" href="#apehub-web-s-three-api-groups" aria-label="Permalink to &quot;Apehub_web&#39;s Three API Groups&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Example</th><th>Auth</th></tr></thead><tbody><tr><td>Public website APIs</td><td><code>/api/v1/apehub-web/site/public/*</code></td><td>No login required</td></tr><tr><td>Developer APIs</td><td><code>/api/v1/apehub-web/developer/*</code></td><td>JWT login</td></tr><tr><td>Admin APIs</td><td><code>/api/v1/apehub-web/admin/*</code></td><td>JWT + plugin permission</td></tr></tbody></table><p>Public APIs only return enabled, published data; developer APIs only access the developer&#39;s own plugins; admin APIs are protected by <code>apehub_web:*</code> menu permissions.</p>`,15)])])}const b=a(i,[["render",o]]);export{h as __pageData,b as default};
